import {finiteGeometry,paperGeometry} from './paper-physics.js';
import * as THREE from './vendor/three.module.js';
import {letterForm} from './letter-forms.js';
const ease=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t);};
export function createWallLetters({scene,board,camera,renderer,sound,reduced,canStart}){
 const items=new Map(),ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let flight=null,view=null,saved=null,clock=0;
 const access=document.createElement('div');access.id='wall-letter-access';access.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:3';document.body.append(access);
 const leave=document.createElement('button');leave.textContent='STEP BACK';leave.hidden=true;leave.style.cssText='position:fixed;bottom:24px;right:24px;background:#ded8c9;border:0;padding:10px;font:10px monospace;letter-spacing:1px;z-index:6;color:#514a3c';leave.onclick=()=>{view=null;leave.hidden=true;};document.body.append(leave);
 function paint(l,form){const c=document.createElement('canvas');c.width=768;c.height=Math.round(768*l.height/l.width);const ctx=c.getContext('2d');ctx.fillStyle=form.color;ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle=`rgba(135,105,51,${(l.age||0)*.22})`;ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#887b5b25';ctx.lineWidth=2;for(const q of [1/3,2/3]){ctx.beginPath();ctx.moveTo(0,c.height*q);ctx.lineTo(c.width,c.height*q+3);ctx.stroke();}ctx.fillStyle=`rgba(57,51,40,${.88-(l.age||0)*.3})`;const font=(l.message||'').length<120?48:l.width<.8?44:36;ctx.font=font+'px "Courier New", monospace';let y=86,line='';for(const ch of l.message||''){if(ch==='\n'||ctx.measureText(line+ch).width>c.width-100){ctx.fillText(line,50,y);y+=font*1.35;line='';if(ch==='\n')continue;}line+=ch;}ctx.fillText(line,50,y);if(l.optionalUrl){ctx.font='21px monospace';ctx.fillText('ATTACHED →',50,c.height-42);}const h=form.hash;ctx.fillStyle=`rgba(117,89,51,${.025+(l.age||0)*.09})`;for(let i=0;i<32;i++){ctx.beginPath();ctx.ellipse((h+i*113)%768,(h+i*173)%c.height,1+i%4,2+i%8,.7,0,7);ctx.fill();}const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=8;return texture;}
 function pressLayers(l,z){
 board.updateMatrixWorld(true);const seen=new Set();for(const group of board.children){if(!group.isGroup)continue;for(const old of group.children){if(!old.isMesh||old.geometry.type==='SphereGeometry'||seen.has(old.geometry)||!old.geometry.attributes.position)continue;seen.add(old.geometry);const p=old.geometry.attributes.position;old.geometry.userData.restPositions??=p.array.slice();let changed=false;for(let n=0;n<p.count;n++){const v=board.worldToLocal(old.localToWorld(new THREE.Vector3(p.getX(n),p.getY(n),p.getZ(n))));const dx=v.x-l.wallX,dy=v.y-l.wallY,x=dx*Math.cos(l.rotation)+dy*Math.sin(l.rotation),y=-dx*Math.sin(l.rotation)+dy*Math.cos(l.rotation);if(Math.abs(x)<l.width/2+.015&&Math.abs(y)<l.height/2+.015&&v.z>z-.008){p.setZ(n,p.getZ(n)-(v.z-z+.008));changed=true;}}if(changed){finiteGeometry(old.geometry,old.geometry.userData.restPositions,.35);p.needsUpdate=true;old.geometry.computeVertexNormals();}}}
 }
 function make(l,mesh){pressLayers(l,.15+Math.min(l.layer||1,1000)*.0006);const form=letterForm(l.id,l.createdAt);form.color=new THREE.Color(form.color).lerp(new THREE.Color('#cabc93'),form.age*.2).getStyle();const group=new THREE.Group();board.add(group);group.position.set(l.wallX,l.wallY,.15+Math.min(l.layer||1,1000)*.0006);group.rotation.z=l.rotation;const g=paperGeometry(l.width,l.height,true),p=g.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i)/l.width+.5,y=p.getY(i)/l.height+.5;p.setZ(i,p.getZ(i)+Math.max(0,x-y-.6)**2*(.25+(l.age||0)*.4)+Math.sin(y*6.28)*.007);if((l.age||0)>.1&&x>.99&&y>.22&&y<.30)p.setX(i,p.getX(i)-l.width*(l.age||0)*.025);if(l.remnant&&y<.7)p.setY(i,l.height*(-.2+y*.07));}g.computeVertexNormals();const mat=new THREE.MeshStandardMaterial({map:l.ghost?null:paint(l,form),color:l.ghost?'#bdb39b':'#ffffff',transparent:!!l.ghost,opacity:l.ghost?.21:1,side:THREE.FrontSide,roughness:.98});mesh=mesh||new THREE.Mesh();mesh.geometry=g;mesh.material=mat;mesh.position.set(0,0,0);mesh.rotation.set(0,0,0);mesh.scale.set(1,1,1);mesh.visible=true;mesh.castShadow=!l.ghost;mesh.receiveShadow=true;mesh.userData.wallId=l.id;group.add(mesh);
 const tack=new THREE.Mesh(new THREE.SphereGeometry(.024,8,6),new THREE.MeshStandardMaterial({color:l.ghost?'#423c30':(l.age||0)>.4?'#665744':'#655d50',roughness:.66,metalness:.55}));tack.scale.z=.35;tack.position.set(-l.width*.25,l.height*.43,.017);group.add(tack);
 const b=document.createElement('button');b.className='physical-letter-control';b.setAttribute('aria-label',l.ghost?'Paper remnant':'Read pinned letter');b.onclick=()=>focus(l.id);access.append(b);
 const text=document.createElement('span');text.className='sr-only';text.id='wall-text-'+l.id;b.setAttribute('aria-describedby',text.id);text.textContent=l.ghost?'A pin hole and traces of paper.':l.message;b.append(text);
 let link=null;if(l.optionalUrl&&!l.ghost){try{const u=new URL(l.optionalUrl);if(['https:','http:'].includes(u.protocol)&&!u.username&&!u.password){link=document.createElement('a');link.href=u.href;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label','Attached link');link.style.cssText='position:fixed;width:100px;height:30px;pointer-events:auto;opacity:0';access.append(link);}}catch{}}
 const item={l,group,mesh,tack,b,link};items.set(l.id,item);return item;}
 function remove(item){if(view===item){view=null;leave.hidden=true;}item.group.removeFromParent();item.mesh.geometry.dispose();item.mesh.material.map?.dispose();item.mesh.material.dispose();item.b.remove();item.link?.remove();items.delete(item.l.id);}
 function sync(records,skip){const ids=new Set(records.map(l=>l.id));for(const item of items.values())if(!ids.has(item.l.id)&&item!==flight?.item)remove(item);for(const l of [...records].sort((a,b)=>a.layer-b.layer)){if(l.id===skip)continue;const old=items.get(l.id);if(old&&old.l.wallState===l.wallState&&old.l.message===l.message&&old.l.optionalUrl===l.optionalUrl&&Math.floor(old.l.age*200)===Math.floor(l.age*200)&&old.l.ghost===l.ghost&&old.l.remnant===l.remnant)continue;const wasView=view===old;if(old)remove(old);const item=make(l);if(wasView){view=item;leave.hidden=false;}} }
 function remember(){if(!saved)saved={position:camera.position.clone(),quaternion:camera.quaternion.clone()};}
 function focus(id){if(flight||!canStart())return;const item=items.get(id);if(!item||item.l.ghost)return;remember();view=item;leave.hidden=false;leave.focus({preventScroll:true});}
 function hit(e){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);return ray.intersectObjects([...items.values()].filter(i=>!i.l.ghost).map(i=>i.mesh))[0]?.object.userData.wallId;}
 let down=null;renderer.domElement.addEventListener('pointerdown',e=>{if(flight||!canStart())return;const id=hit(e);if(id){down={id,x:e.clientX,y:e.clientY};e.stopImmediatePropagation();}},true);renderer.domElement.addEventListener('pointerup',e=>{if(!down)return;const d=down;down=null;e.stopImmediatePropagation();if(Math.hypot(e.clientX-d.x,e.clientY-d.y)<12)focus(d.id);},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&view){view=null;leave.hidden=true;}});
 function pin(selected,records,done){remember();const l=records.find(l=>l.id===selected.id);if(!l){done();return;}sync(records,l.id);const old=items.get(l.id);if(old)remove(old);scene.updateMatrixWorld(true);const start=selected.mesh.getWorldPosition(new THREE.Vector3()),q=selected.mesh.getWorldQuaternion(new THREE.Quaternion()),scale=selected.mesh.scale.clone();const item=make(l,selected.mesh);const end=item.mesh.getWorldPosition(new THREE.Vector3()),endQ=item.mesh.getWorldQuaternion(new THREE.Quaternion());scene.attach(item.mesh);item.mesh.position.copy(start);item.mesh.quaternion.copy(q);item.mesh.scale.copy(scale);item.tack.visible=false;flight={item,start,q,scale,end,endQ,age:0,done,contact:false};}
 function update(dt){clock+=dt;document.body.classList.toggle('wall-reading',!!saved);
  const destination=flight?.item||view;
  if(saved){let pos=saved.position,quat=saved.quaternion;if(destination){const target=destination.group.getWorldPosition(new THREE.Vector3());const distance=Math.max(1.8, destination.l.height/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*1.6, destination.l.width*1.35/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))*camera.aspect)*1.12);pos=target.clone().add(new THREE.Vector3(0,0,flight?Math.max(distance,7):distance));const dummy=new THREE.PerspectiveCamera();dummy.position.copy(pos);dummy.lookAt(target);quat=dummy.quaternion;}
   const a=reduced?1:1-Math.exp(-dt*2.8);camera.position.lerp(pos,a);camera.quaternion.slerp(quat,a);if(!destination&&camera.position.distanceTo(saved.position)<.01){camera.position.copy(saved.position);camera.quaternion.copy(saved.quaternion);saved=null;}}
  if(flight){const f=flight;f.age+=dt;const t=reduced?1:ease(f.age/2.5);f.item.mesh.position.lerpVectors(f.start,f.end,t);f.item.mesh.position.y+=Math.sin(t*Math.PI)*.16;f.item.mesh.quaternion.slerpQuaternions(f.q,f.endQ,t);f.item.mesh.scale.lerpVectors(f.scale,new THREE.Vector3(1.35,1,1),t);if(t===1&&!f.contact){f.contact=true;sound('contact','folded',.025);}if(f.age>=2.65||reduced){if(!f.tacked){f.tacked=true;sound('impact','folded',.035);}f.item.tack.visible=true;f.item.tack.position.z=.017+Math.max(0,1-(f.age-2.65)*6)*.2;f.item.mesh.position.z+=Math.sin((f.age-2.65)*50)*Math.exp(-(f.age-2.65)*14)*.009;}if(f.age>=3.3||reduced){f.item.group.attach(f.item.mesh);f.item.mesh.position.set(0,0,0);f.item.mesh.rotation.set(0,0,0);f.item.mesh.scale.set(1,1,1);view=f.item;leave.hidden=false;flight=null;f.done();leave.focus({preventScroll:true});}}
  const r=renderer.domElement.getBoundingClientRect();for(const i of items.values()){if(i!==flight?.item)i.mesh.position.z=THREE.MathUtils.lerp(i.mesh.position.z,view===i?.018:0,Math.min(1,dt*5));const v=i.group.getWorldPosition(new THREE.Vector3()).project(camera);i.b.style.left=r.left+(v.x*.5+.5)*r.width-22+'px';i.b.style.top=r.top+(-v.y*.5+.5)*r.height-20+'px';i.b.hidden=!!flight||!canStart();if(i.link){const p=i.group.localToWorld(new THREE.Vector3(-i.l.width*.23,-i.l.height/2+.07,.02)).project(camera);i.link.style.left=r.left+(p.x*.5+.5)*r.width-50+'px';i.link.style.top=r.top+(-p.y*.5+.5)*r.height-15+'px';i.link.hidden=view!==i;}}
 }
 return {resize(){if(!flight){saved=null;view=null;leave.hidden=true;}},sync,pin,update,get active(){return !!saved;}};
}
